  const decode = s => { let n = 0; for (const c of s) n = n * 64 + ALPHABET.indexOf(c); return n; };
  let extraMap = null;   // 码位偏移 → 其余读音的下标;第一次用到才建
  function extras() {
    if (extraMap) return extraMap;
    extraMap = new Map();
    for (let i = 0; i < EXTRA.length;) {
      const offset = decode(EXTRA.slice(i, i + 3)), count = decode(EXTRA.slice(i + 3, i + 4));
      const list = [];
      for (let k = 0; k < count; k += 1) list.push(decode(EXTRA.slice(i + 4 + k * 2, i + 6 + k * 2)));
      extraMap.set(offset, list);
      i += 4 + count * 2;
    }
    return extraMap;
  }
  // 一个字的全部读音(主读音在前);表外的字(英文、标点、扩展区汉字)回空数组。
  function readings(ch) {
    const code = String(ch || '').codePointAt(0);   // 不叫 cp:依赖图扫描器会把它认成 00-boot 的 child_process
    if (!(code >= FROM && code <= TO)) return [];
    const offset = code - FROM;
    const first = decode(PRIMARY.slice(offset * 2, offset * 2 + 2));
    if (!first) return [];
    return [first, ...(extras().get(offset) || [])].map(i => SYLLABLES[i - 1]);
  }
  return Object.freeze({ FROM, TO, COUNT, SYLLABLE_COUNT: SYLLABLES.length, readings });
